        isWorkbenchApp: true,
        isBlueprints: true,
        minify: true,
        outDir,
        output,
        reactCompiler: false,
        schemaExtraction: undefined,
        sourceMap: false,
        stats: false,
        unattendedMode: true,
        vite: undefined,
